package com.bank.app;

import java.math.BigDecimal;
import java.util.logging.*;

// Independent entry point — a standalone nightly batch, started by naming THIS class.
public class SettlementJob {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String date = args.length > 0 ? args[0] : "2026-10-30";
        log.info(() -> "SettlementJob.main() — standalone batch entry point for " + date);
        BigDecimal rentAmount = new BigDecimal("50000.00");
        log.info(() -> "Settling Rs." + rentAmount + " transfers from SAV2001 to CUR3001");
        // ... batch settlement logic; typically does NOT start the web context
        log.info("Settlement batch complete.");
    }
}
